  'calc.comoFunciona': 'How it works',
  'calc.mlBrasilFreteCalloutTexto': 'The shipping cost is automatically deducted from your sale by Mercado Livre, even when the buyer pays for shipping. It depends on the packaging weight and the listing\'s price tier. The values already include a discount of up to 70% for a green reputation.',
