  'calc.pesoEmbaladoFaixaFreteHint': 'Total weight of the packaged item, sets the shipping table tier.',
  'calc.mlBrasilFreteAbaixo19Hint': 'Listings under R$ 19 pay, at most, half the product price in shipping. Calculated after clicking "Calculate", using the consumer price. Estimated values, check against the official table (29 weight tiers × 8 price tiers).',
  'calc.mlArgentinaFreteCalloutTexto': 'The cost per unit sold is automatically deducted from your sale by Mercado Livre. It depends on the packaging weight and the listing\'s price tier.',
  'calc.mlArgentinaCalculadoAposClicarHint': 'Calculated after clicking "Calculate", using the consumer price. Official source captured on 09/16/2026, valid for products under $33,000; above that, we reapply the "$24,000 to $32,999" tier because there is no official table for that range.',
