  'calc.shopeeVigenciaTexto': 'Commission policy announced by Shopee on 09/18/2026. The fixed fee per item up to R$ 79.99 went from R$ 4.00 to R$ 4.50, and the low-value rule threshold for CNPJ went from R$ 8 to R$ 9. Percentages, other tiers and the Pix subsidy did not change.',
  'calc.shopeeVigenciaLink': 'View policy on Shopee',
