  'calc.shopeeRegrasBaixoValorTitulo': 'Low-value rules',
  'calc.shopeeRegrasBaixoValorTexto': 'CNPJ (business tax ID) with a product under R$ 9.00: the fixed fee becomes 50% of the product value. CPF (individual tax ID) with a product under R$ 12.00: regressive fee (R$ 6.00 up to R$ 8.00; R$ 6.50 between R$ 8.00 and R$ 12.00).',
  'calc.shopeeProgramaFreteGratisHint': 'The Free Shipping Program offers coupons of up to R$20 (items up to R$79.99), R$30 (R$80 to R$199.99) and R$40 (over R$200). The shipping subsidy and the Pix subsidy are informational only and are not included in this calculation.',
