export const DICIONARIOS: Record<Idioma, Dicionario> = { pt, en, es };

export function traduzir(idioma: Idioma, chave: string): string {
  return DICIONARIOS[idioma][chave] ?? DICIONARIOS[IDIOMA_PADRAO][chave] ?? chave;
}
